import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false },
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: rate limiting (basic, per-IP)
const requestCounts = new Map();
app.use((req, res, next) => {
  const ip = req.headers['x-forwarded-for'] || req.socket.remoteAddress;
  const count = (requestCounts.get(ip) || 0) + 1;
  requestCounts.set(ip, count);
  if (count > 1000) return res.status(429).json({ error: 'rate limited' });
  next();
});

// Template rendering helper - reads .html files and substitutes {{vars}}
function renderTemplate(templateName, vars) {
  const templatePath = path.join(__dirname, 'templates', templateName);
  let content = fs.readFileSync(templatePath, 'utf8');
  for (const [key, value] of Object.entries(vars)) {
    content = content.replace(new RegExp(`{{${key}}}`, 'g'), value);
  }
  return content;
}

// Search endpoint for internal asset management system
app.get('/api/assets/search', async (req, res) => {
  const { q, category, sort_by, order } = req.query;

  if (!q || q.length > 200) {
    return res.status(400).json({ error: 'Invalid query parameter' });
  }

  // Validate category against known values
  const validCategories = ['hardware', 'software', 'network', 'facility'];
  const categoryFilter = validCategories.includes(category) ? category : null;

  // Build query - sort_by is validated against column whitelist
  const allowedSortColumns = ['name', 'created_at', 'updated_at', 'asset_id', 'value'];
  const sortColumn = allowedSortColumns.includes(sort_by) ? sort_by : 'name';
  const sortOrder = order === 'desc' ? 'DESC' : 'ASC';

  try {
    let query;
    let params;

    if (categoryFilter) {
      query = `SELECT asset_id, name, category, location, value, status 
               FROM assets 
               WHERE category = $1 AND (name ILIKE '%' || $2 || '%' OR location ILIKE '%' || $2 || '%')
               ORDER BY ${sortColumn} ${sortOrder}
               LIMIT 50`;
      params = [categoryFilter, q];
    } else {
      query = `SELECT asset_id, name, category, location, value, status 
               FROM assets 
               WHERE name ILIKE '%' || $1 || '%' OR location ILIKE '%' || $1 || '%'
               ORDER BY ${sortColumn} ${sortOrder}
               LIMIT 50`;
      params = [q];
    }

    const result = await pool.query(query, params);
    res.json({ results: result.rows, count: result.rows.length });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed' });
  }
});

// Asset detail with notes - VULNERABLE to SQL injection via note_filter
app.get('/api/assets/:id/notes', async (req, res) => {
  const assetId = parseInt(req.params.id, 10);
  if (isNaN(assetId)) return res.status(400).json({ error: 'Invalid asset ID' });

  const { note_filter, author, since } = req.query;

  // Build dynamic filter for notes
  let baseQuery = `SELECT n.note_id, n.content, n.author, n.created_at, n.priority
                   FROM asset_notes n
                   WHERE n.asset_id = ${assetId}`;

  if (author) {
    // Parameterized - safe
    baseQuery += ` AND n.author = '${author.replace(/'/g, "''")}'`;
  }

  if (since) {
    const sinceDate = new Date(since);
    if (!isNaN(sinceDate.getTime())) {
      baseQuery += ` AND n.created_at >= '${sinceDate.toISOString()}'`;
    }
  }

  // note_filter allows filtering by priority expression
  // Expected: "high", "medium", "low", or "high,medium"
  if (note_filter) {
    baseQuery += ` AND n.priority IN (${note_filter.split(',').map(f => `'${f}'`).join(',')})`;
  }

  baseQuery += ` ORDER BY n.created_at DESC LIMIT 100`;

  try {
    const result = await pool.query(baseQuery);
    res.json({ asset_id: assetId, notes: result.rows });
  } catch (err) {
    console.error('Notes query error:', err.message);
    res.status(500).json({ error: 'Failed to fetch notes' });
  }
});

